SELECT *
FROM user_friend
WHERE user_id = #{userId}
    OR friend_id = #{userId}

SELECT COUNT(*)
FROM user_friend
WHERE user_id = #{userId}
    OR friend_id = #{userId}

SELECT CASE WHEN uf.user_id = #{userId} THEN uf.friend_id ELSE uf.user_id END AS userId, CASE WHEN uf.user_id = #{userId} THEN luf.user_name ELSE luu.user_name END AS userName, CASE WHEN uf.user_id = #{userId} THEN luf.avatar_file_id ELSE luu.avatar_file_id END AS avatarFileId, CASE WHEN uf.user_id = #{userId} THEN luf.account ELSE luu.account END AS userAccount, CASE WHEN uf.user_id = #{userId} THEN uf.remark_user_for_friend ELSE uf.remark_friend_for_user END AS remark FROM user_friend uf JOIN login_user luu ON uf.user_id = luu.id JOIN login_user luf ON uf.friend_id = luf.id WHERE (uf.user_id = #{userId} OR uf.friend_id = #{userId})
AND ((uf.friend_id IN
#{friendId}
) OR (uf.user_id IN
#{friendId}
))
